#!/usr/bin/env node
'use strict';
// Deck3 intent classification: routing only; NOT a claim of PPTX execution.
const route=function route(prompt){const s=String(prompt||"").trim().toLowerCase().replace(/^deck3\b[\s:,-]*/,"");const slideMatch=s.match(/\bslide\s*(\d{1,3})\b/);const slide=slideMatch?Number(slideMatch[1]):null;let intent="status";if(/\b(update|upgrade)\b/.test(s)&&/\b(skill|agent|ecosystem|workflow|color|palette|deck3)\b/.test(s))intent="ecosystem_update";else if(/\b(audit|qa|verify|test|check)\b/.test(s))intent="audit";else if(/\b(compare|rank|grade)\b/.test(s))intent="compare";else if(/\b(animate|animation|reveal)\b/.test(s))intent="animate";else if(/\b(math|latex|equation|omml|main\.tex)\b/.test(s))intent="math";else if(/\b(assemble|assembly|combine)\b/.test(s))intent="assemble";else if(/\b(figure|image|infographic|diagram|illustration)\b/.test(s))intent="figure";else if(/\b(edit|improve|revise|modify|fix)\b/.test(s))intent="edit";else if(/\b(template|analyze|inspect)\b/.test(s))intent="template_inspect";else if(/\b(text|writing|notes|outline)\b/.test(s)||s==="1")intent="text";else if(/\ball\b/.test(s))intent="all";else if(slide!==null)intent="slide";else if(/\b(generate|create|build)\b/.test(s))intent="all";else if(s==="2")intent="figure";else if(s==="3")intent="assemble";if(slide!==null&&(slide<1||slide>13))return {intent:"blocked",slide,reason:"slide_outside_approved_13_slide_baseline",scientific_status:"OPEN"};const media=slide===6||slide===7||slide===8||slide===10||slide===11||slide===13?"native_editable":slide===3||slide===4||slide===5||slide===9||slide===12?"qualified_physical_visual":"purpose_selected";return {intent,slide,media,assurance:"NOT_RUN",requires_source_inspection:true};};
if(require.main===module){const input=process.argv.slice(2).join(' ');process.stdout.write(JSON.stringify(route(input),null,2)+'\n');}
module.exports={route};
